#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

using std::size_t;

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    size_t q1 = 0, q2 = 0, q3 = 0, q4 = 0;

    #pragma omp parallel for reduction(+:q1,q2,q3,q4)
    for (size_t i = 0; i < points.size(); ++i) {
        const Point& p = points[i];

        if (p.x > 0.0 && p.y > 0.0) {
            ++q1; // Quadrant I
        } else if (p.x < 0.0 && p.y > 0.0) {
            ++q2; // Quadrant II
        } else if (p.x < 0.0 && p.y < 0.0) {
            ++q3; // Quadrant III
        } else if (p.x > 0.0 && p.y < 0.0) {
            ++q4; // Quadrant IV
        }
        // Points on an axis are not in any quadrant, so they are ignored.
    }

    bins[0] = q1;
    bins[1] = q2;
    bins[2] = q3;
    bins[3] = q4;
}
